     1→//! Collection of methods for block validation.
     2→
     3→use alloy_consensus::{
     4→    constants::MAXIMUM_EXTRA_DATA_SIZE, BlockHeader as _, Transaction, EMPTY_OMMER_ROOT_HASH,
     5→};
     6→use alloy_eips::{eip4844::DATA_GAS_PER_BLOB, eip7840::BlobParams};
     7→use reth_chainspec::{EthChainSpec, EthereumHardfork, EthereumHardforks};
     8→use reth_consensus::{ConsensusError, TxGasLimitTooHighErr};
     9→use reth_primitives_traits::{
    10→    constants::{
    11→        GAS_LIMIT_BOUND_DIVISOR, MAXIMUM_GAS_LIMIT_BLOCK, MAX_TX_GAS_LIMIT_OSAKA, MINIMUM_GAS_LIMIT,
    12→    },
    13→    Block, BlockBody, BlockHeader, GotExpected, SealedBlock, SealedHeader, SignedTransaction,
    14→};
    15→
    16→/// The maximum RLP length of a block, defined in [EIP-7934](https://eips.ethereum.org/EIPS/eip-7934).
    17→///
    18→/// Calculated as `MAX_BLOCK_SIZE` - `SAFETY_MARGIN` where
    19→/// `MAX_BLOCK_SIZE` = `10_485_760`
    20→/// `SAFETY_MARGIN` = `2_097_152`
    21→pub const MAX_RLP_BLOCK_SIZE: usize = 8_388_608;
    22→
    23→/// Gas used needs to be less than gas limit. Gas used is going to be checked after execution.
    24→#[inline]
    25→pub fn validate_header_gas<H: BlockHeader>(header: &H) -> Result<(), ConsensusError> {
    26→    if header.gas_used() > header.gas_limit() {
    27→        return Err(ConsensusError::HeaderGasUsedExceedsGasLimit {
    28→            gas_used: header.gas_used(),
    29→            gas_limit: header.gas_limit(),
    30→        })
    31→    }
    32→    // Check that the gas limit is below the maximum allowed gas limit
    33→    if header.gas_limit() > MAXIMUM_GAS_LIMIT_BLOCK {
    34→        return Err(ConsensusError::HeaderGasLimitExceedsMax { gas_limit: header.gas_limit() })
    35→    }
    36→    Ok(())
    37→}
    38→
    39→/// Ensure the EIP-1559 base fee is set if the London hardfork is active.
    40→#[inline]
    41→pub fn validate_header_base_fee<H: BlockHeader, ChainSpec: EthereumHardforks>(
    42→    header: &H,
    43→    chain_spec: &ChainSpec,
    44→) -> Result<(), ConsensusError> {
    45→    if chain_spec.is_london_active_at_block(header.number()) && header.base_fee_per_gas().is_none()
    46→    {
    47→        return Err(ConsensusError::BaseFeeMissing)
    48→    }
    49→    Ok(())
    50→}
    51→
    52→/// Validate that withdrawals are present in Shanghai
    53→///
    54→/// See [EIP-4895]: Beacon chain push withdrawals as operations
    55→///
    56→/// [EIP-4895]: https://eips.ethereum.org/EIPS/eip-4895
    57→#[inline]
    58→pub fn validate_shanghai_withdrawals<B: Block>(
    59→    block: &SealedBlock<B>,
    60→) -> Result<(), ConsensusError> {
    61→    let withdrawals = block.body().withdrawals().ok_or(ConsensusError::BodyWithdrawalsMissing)?;
    62→    let withdrawals_root = alloy_consensus::proofs::calculate_withdrawals_root(withdrawals);
    63→    let header_withdrawals_root =
    64→        block.withdrawals_root().ok_or(ConsensusError::WithdrawalsRootMissing)?;
    65→    if withdrawals_root != *header_withdrawals_root {
    66→        return Err(ConsensusError::BodyWithdrawalsRootDiff(
    67→            GotExpected { got: withdrawals_root, expected: header_withdrawals_root }.into(),
    68→        ));
    69→    }
    70→    Ok(())
    71→}
    72→
    73→/// Validate that blob gas is present in the block if Cancun is active.
    74→///
    75→/// See [EIP-4844]: Shard Blob Transactions
    76→///
    77→/// [EIP-4844]: https://eips.ethereum.org/EIPS/eip-4844
    78→#[inline]
    79→pub fn validate_cancun_gas<B: Block>(block: &SealedBlock<B>) -> Result<(), ConsensusError> {
    80→    // Check that the blob gas used in the header matches the sum of the blob gas used by each
    81→    // blob tx
    82→    let header_blob_gas_used = block.blob_gas_used().ok_or(ConsensusError::BlobGasUsedMissing)?;
    83→    let total_blob_gas = block.body().blob_gas_used();
    84→    if total_blob_gas != header_blob_gas_used {
    85→        return Err(ConsensusError::BlobGasUsedDiff(GotExpected {
    86→            got: header_blob_gas_used,
    87→            expected: total_blob_gas,
    88→        }));
    89→    }
    90→    Ok(())
    91→}
    92→
    93→/// Ensures the block response data matches the header.
    94→///
    95→/// This ensures the body response items match the header's hashes:
    96→///   - ommer hash
    97→///   - transaction root
    98→///   - withdrawals root
    99→pub fn validate_body_against_header<B, H>(body: &B, header: &H) -> Result<(), ConsensusError>
   100→where
   101→    B: BlockBody,
   102→    H: BlockHeader,
   103→{
   104→    let ommers_hash = body.calculate_ommers_root();
   105→    if Some(header.ommers_hash()) != ommers_hash {
   106→        return Err(ConsensusError::BodyOmmersHashDiff(
   107→            GotExpected {
   108→                got: ommers_hash.unwrap_or(EMPTY_OMMER_ROOT_HASH),
   109→                expected: header.ommers_hash(),
   110→            }
   111→            .into(),
   112→        ))
   113→    }
   114→
   115→    let tx_root = body.calculate_tx_root();
   116→    if header.transactions_root() != tx_root {
   117→        return Err(ConsensusError::BodyTransactionRootDiff(
   118→            GotExpected { got: tx_root, expected: header.transactions_root() }.into(),
   119→        ))
   120→    }
   121→
   122→    match (header.withdrawals_root(), body.calculate_withdrawals_root()) {
   123→        (Some(header_withdrawals_root), Some(withdrawals_root)) => {
   124→            if withdrawals_root != header_withdrawals_root {
   125→                return Err(ConsensusError::BodyWithdrawalsRootDiff(
   126→                    GotExpected { got: withdrawals_root, expected: header_withdrawals_root }.into(),
   127→                ))
   128→            }
   129→        }
   130→        (None, None) => {
   131→            // this is ok because we assume the fork is not active in this case
   132→        }
   133→        _ => return Err(ConsensusError::WithdrawalsRootUnexpected),
   134→    }
   135→
   136→    Ok(())
   137→}
   138→
   139→/// Validate a block without regard for state:
   140→///
   141→/// - Compares the ommer hash in the block header to the block body
   142→/// - Compares the transactions root in the block header to the block body
   143→/// - Pre-execution transaction validation
   144→pub fn validate_block_pre_execution<B, ChainSpec>(
   145→    block: &SealedBlock<B>,
   146→    chain_spec: &ChainSpec,
   147→) -> Result<(), ConsensusError>
   148→where
   149→    B: Block,
   150→    ChainSpec: EthereumHardforks,
   151→{
   152→    post_merge_hardfork_fields(block, chain_spec)?;
   153→
   154→    // Check transaction root
   155→    if let Err(error) = block.ensure_transaction_root_valid() {
   156→        return Err(ConsensusError::BodyTransactionRootDiff(error.into()))
   157→    }
   158→    // EIP-7825 validation
   159→    if chain_spec.is_osaka_active_at_timestamp(block.timestamp()) {
   160→        for tx in block.body().transactions() {
   161→            if tx.gas_limit() > MAX_TX_GAS_LIMIT_OSAKA {
   162→                return Err(TxGasLimitTooHighErr {
   163→                    tx_hash: *tx.tx_hash(),
   164→                    gas_limit: tx.gas_limit(),
   165→                    max_allowed: MAX_TX_GAS_LIMIT_OSAKA,
   166→                }
   167→                .into());
   168→            }
   169→        }
   170→    }
   171→
   172→    Ok(())
   173→}
   174→
   175→/// Validates the ommers hash and other fork-specific fields.
   176→///
   177→/// These fork-specific validations are:
   178→/// * EIP-4895 withdrawals validation, if shanghai is active based on the given chainspec. See more
   179→///   information about the specific checks in [`validate_shanghai_withdrawals`].
   180→/// * EIP-4844 blob gas validation, if cancun is active based on the given chainspec. See more
   181→///   information about the specific checks in [`validate_cancun_gas`].
   182→/// * EIP-7934 block size limit validation, if osaka is active based on the given chainspec.
   183→pub fn post_merge_hardfork_fields<B, ChainSpec>(
   184→    block: &SealedBlock<B>,
   185→    chain_spec: &ChainSpec,
   186→) -> Result<(), ConsensusError>
   187→where
   188→    B: Block,
   189→    ChainSpec: EthereumHardforks,
   190→{
   191→    // Check ommers hash
   192→    let ommers_hash = block.body().calculate_ommers_root();
   193→    if Some(block.ommers_hash()) != ommers_hash {
   194→        return Err(ConsensusError::BodyOmmersHashDiff(
   195→            GotExpected {
   196→                got: ommers_hash.unwrap_or(EMPTY_OMMER_ROOT_HASH),
   197→                expected: block.ommers_hash(),
   198→            }
   199→            .into(),
   200→        ))
   201→    }
   202→
   203→    // EIP-4895: Beacon chain push withdrawals as operations
   204→    if chain_spec.is_shanghai_active_at_timestamp(block.timestamp()) {
   205→        validate_shanghai_withdrawals(block)?;
   206→    }
   207→
   208→    if chain_spec.is_cancun_active_at_timestamp(block.timestamp()) {
   209→        validate_cancun_gas(block)?;
   210→    }
   211→
   212→    if chain_spec.is_osaka_active_at_timestamp(block.timestamp()) &&
   213→        block.rlp_length() > MAX_RLP_BLOCK_SIZE
   214→    {
   215→        return Err(ConsensusError::BlockTooLarge {
   216→            rlp_length: block.rlp_length(),
   217→            max_rlp_length: MAX_RLP_BLOCK_SIZE,
   218→        })
   219→    }
   220→
   221→    Ok(())
   222→}
   223→
   224→/// Validates that the EIP-4844 header fields exist and conform to the spec. This ensures that:
   225→///
   226→///  * `blob_gas_used` exists as a header field
   227→///  * `excess_blob_gas` exists as a header field
   228→///  * `parent_beacon_block_root` exists as a header field
   229→///  * `blob_gas_used` is a multiple of `DATA_GAS_PER_BLOB`
   230→///  * `excess_blob_gas` is a multiple of `DATA_GAS_PER_BLOB`
   231→///  * `blob_gas_used` doesn't exceed the max allowed blob gas based on the given params
   232→///
   233→/// Note: This does not enforce any restrictions on `blob_gas_used`
   234→pub fn validate_4844_header_standalone<H: BlockHeader>(
   235→    header: &H,
   236→    blob_params: BlobParams,
   237→) -> Result<(), ConsensusError> {
   238→    let blob_gas_used = header.blob_gas_used().ok_or(ConsensusError::BlobGasUsedMissing)?;
   239→
   240→    if header.parent_beacon_block_root().is_none() {
   241→        return Err(ConsensusError::ParentBeaconBlockRootMissing)
   242→    }
   243→
   244→    if !blob_gas_used.is_multiple_of(DATA_GAS_PER_BLOB) {
   245→        return Err(ConsensusError::BlobGasUsedNotMultipleOfBlobGasPerBlob {
   246→            blob_gas_used,
   247→            blob_gas_per_blob: DATA_GAS_PER_BLOB,
   248→        })
   249→    }
   250→
   251→    if blob_gas_used > blob_params.max_blob_gas_per_block() {
   252→        return Err(ConsensusError::BlobGasUsedExceedsMaxBlobGasPerBlock {
   253→            blob_gas_used,
   254→            max_blob_gas_per_block: blob_params.max_blob_gas_per_block(),
   255→        })
   256→    }
   257→
   258→    Ok(())
   259→}
   260→
   261→/// Validates the header's extra data according to the beacon consensus rules.
   262→///
   263→/// From yellow paper: extraData: An arbitrary byte array containing data relevant to this block.
   264→/// This must be 32 bytes or fewer; formally Hx.
   265→#[inline]
   266→pub fn validate_header_extra_data<H: BlockHeader>(header: &H) -> Result<(), ConsensusError> {
   267→    let extra_data_len = header.extra_data().len();
   268→    if extra_data_len > MAXIMUM_EXTRA_DATA_SIZE {
   269→        Err(ConsensusError::ExtraDataExceedsMax { len: extra_data_len })
   270→    } else {
   271→        Ok(())
   272→    }
   273→}
   274→
   275→/// Validates against the parent hash and number.
   276→///
   277→/// This function ensures that the header block number is sequential and that the hash of the parent
   278→/// header matches the parent hash in the header.
   279→#[inline]
   280→pub fn validate_against_parent_hash_number<H: BlockHeader>(
   281→    header: &H,
   282→    parent: &SealedHeader<H>,
   283→) -> Result<(), ConsensusError> {
   284→    // Parent number is consistent.
   285→    if parent.number() + 1 != header.number() {
   286→        return Err(ConsensusError::ParentBlockNumberMismatch {
   287→            parent_block_number: parent.number(),
   288→            block_number: header.number(),
   289→        })
   290→    }
   291→
   292→    if parent.hash() != header.parent_hash() {
   293→        return Err(ConsensusError::ParentHashMismatch(
   294→            GotExpected { got: header.parent_hash(), expected: parent.hash() }.into(),
   295→        ))
   296→    }
   297→
   298→    Ok(())
   299→}
   300→
   301→/// Validates the base fee against the parent and EIP-1559 rules.
   302→#[inline]
   303→pub fn validate_against_parent_eip1559_base_fee<ChainSpec: EthChainSpec + EthereumHardforks>(
   304→    header: &ChainSpec::Header,
   305→    parent: &ChainSpec::Header,
   306→    chain_spec: &ChainSpec,
   307→) -> Result<(), ConsensusError> {
   308→    if chain_spec.is_london_active_at_block(header.number()) {
   309→        let base_fee = header.base_fee_per_gas().ok_or(ConsensusError::BaseFeeMissing)?;
   310→
   311→        let expected_base_fee = if chain_spec
   312→            .ethereum_fork_activation(EthereumHardfork::London)
   313→            .transitions_at_block(header.number())
   314→        {
   315→            alloy_eips::eip1559::INITIAL_BASE_FEE
   316→        } else {
   317→            chain_spec
   318→                .next_block_base_fee(parent, header.timestamp())
   319→                .ok_or(ConsensusError::BaseFeeMissing)?
   320→        };
   321→        if expected_base_fee != base_fee {
   322→            return Err(ConsensusError::BaseFeeDiff(GotExpected {
   323→                expected: expected_base_fee,
   324→                got: base_fee,
   325→            }))
   326→        }
   327→    }
   328→
   329→    Ok(())
   330→}
   331→
   332→/// Validates the timestamp against the parent to make sure it is in the past.
   333→#[inline]
   334→pub fn validate_against_parent_timestamp<H: BlockHeader>(
   335→    header: &H,
   336→    parent: &H,
   337→) -> Result<(), ConsensusError> {
   338→    if header.timestamp() <= parent.timestamp() {
   339→        return Err(ConsensusError::TimestampIsInPast {
   340→            parent_timestamp: parent.timestamp(),
   341→            timestamp: header.timestamp(),
   342→        })
   343→    }
   344→    Ok(())
   345→}
   346→
   347→/// Validates gas limit against parent gas limit.
   348→///
   349→/// The maximum allowable difference between self and parent gas limits is determined by the
   350→/// parent's gas limit divided by the [`GAS_LIMIT_BOUND_DIVISOR`].
   351→#[inline]
   352→pub fn validate_against_parent_gas_limit<
   353→    H: BlockHeader,
   354→    ChainSpec: EthChainSpec + EthereumHardforks,
   355→>(
   356→    header: &SealedHeader<H>,
   357→    parent: &SealedHeader<H>,
   358→    chain_spec: &ChainSpec,
   359→) -> Result<(), ConsensusError> {
   360→    // Determine the parent gas limit, considering elasticity multiplier on the London fork.
   361→    let parent_gas_limit = if !chain_spec.is_london_active_at_block(parent.number()) &&
   362→        chain_spec.is_london_active_at_block(header.number())
   363→    {
   364→        parent.gas_limit() *
   365→            chain_spec.base_fee_params_at_timestamp(header.timestamp()).elasticity_multiplier
   366→                as u64
   367→    } else {
   368→        parent.gas_limit()
   369→    };
   370→
   371→    // Check for an increase in gas limit beyond the allowed threshold.
   372→    if header.gas_limit() > parent_gas_limit {
   373→        if header.gas_limit() - parent_gas_limit >= parent_gas_limit / GAS_LIMIT_BOUND_DIVISOR {
   374→            return Err(ConsensusError::GasLimitInvalidIncrease {
   375→                parent_gas_limit,
   376→                child_gas_limit: header.gas_limit(),
   377→            })
   378→        }
   379→    }
   380→    // Check for a decrease in gas limit beyond the allowed threshold.
   381→    else if parent_gas_limit - header.gas_limit() >= parent_gas_limit / GAS_LIMIT_BOUND_DIVISOR {
   382→        return Err(ConsensusError::GasLimitInvalidDecrease {
   383→            parent_gas_limit,
   384→            child_gas_limit: header.gas_limit(),
   385→        })
   386→    }
   387→    // Check if the self gas limit is below the minimum required limit.
   388→    else if header.gas_limit() < MINIMUM_GAS_LIMIT {
   389→        return Err(ConsensusError::GasLimitInvalidMinimum { child_gas_limit: header.gas_limit() })
   390→    }
   391→
   392→    Ok(())
   393→}
   394→
   395→/// Validates that the EIP-4844 header fields are correct with respect to the parent block. This
   396→/// ensures that the `blob_gas_used` and `excess_blob_gas` fields exist in the child header, and
   397→/// that the `excess_blob_gas` field matches the expected `excess_blob_gas` calculated from the
   398→/// parent header fields.
   399→pub fn validate_against_parent_4844<H: BlockHeader>(
   400→    header: &H,
   401→    parent: &H,
   402→    blob_params: BlobParams,
   403→) -> Result<(), ConsensusError> {
   404→    // From [EIP-4844](https://eips.ethereum.org/EIPS/eip-4844#header-extension):
   405→    //
   406→    // > For the first post-fork block, both parent.blob_gas_used and parent.excess_blob_gas
   407→    // > are evaluated as 0.
   408→    //
   409→    // This means in the first post-fork block, calc_excess_blob_gas will return 0.
   410→    let parent_blob_gas_used = parent.blob_gas_used().unwrap_or(0);
   411→    let parent_excess_blob_gas = parent.excess_blob_gas().unwrap_or(0);
   412→
   413→    if header.blob_gas_used().is_none() {
   414→        return Err(ConsensusError::BlobGasUsedMissing)
   415→    }
   416→    let excess_blob_gas = header.excess_blob_gas().ok_or(ConsensusError::ExcessBlobGasMissing)?;
   417→
   418→    let parent_base_fee_per_gas = parent.base_fee_per_gas().unwrap_or(0);
   419→    let expected_excess_blob_gas = blob_params.next_block_excess_blob_gas_osaka(
   420→        parent_excess_blob_gas,
   421→        parent_blob_gas_used,
   422→        parent_base_fee_per_gas,
   423→    );
   424→    if expected_excess_blob_gas != excess_blob_gas {
   425→        return Err(ConsensusError::ExcessBlobGasDiff {
   426→            diff: GotExpected { got: excess_blob_gas, expected: expected_excess_blob_gas },
   427→            parent_excess_blob_gas,
   428→            parent_blob_gas_used,
   429→        })
   430→    }
   431→
   432→    Ok(())
   433→}
