   435→#[cfg(test)]
   436→mod tests {
   437→    use super::*;
   438→    use alloy_consensus::{BlockBody, Header, TxEip4844};
   439→    use alloy_eips::eip4895::Withdrawals;
   440→    use alloy_primitives::{Address, Bytes, Signature, U256};
   441→    use rand::Rng;
   442→    use reth_chainspec::ChainSpecBuilder;
   443→    use reth_ethereum_primitives::{Transaction, TransactionSigned};
   444→    use reth_primitives_traits::proofs;
   445→
   446→    fn mock_blob_tx(nonce: u64, num_blobs: usize) -> TransactionSigned {
   447→        let mut rng = rand::rng();
   448→        let request = Transaction::Eip4844(TxEip4844 {
   449→            chain_id: 1u64,
   450→            nonce,
   451→            max_fee_per_gas: 0x28f000fff,
   452→            max_priority_fee_per_gas: 0x28f000fff,
   453→            max_fee_per_blob_gas: 0x7,
   454→            gas_limit: 10,
   455→            to: Address::default(),
   456→            value: U256::from(3_u64),
   457→            input: Bytes::from(vec![1, 2]),
   458→            access_list: Default::default(),
   459→            blob_versioned_hashes: std::iter::repeat_with(|| rng.random())
   460→                .take(num_blobs)
   461→                .collect(),
   462→        });
   463→
   464→        let signature = Signature::new(U256::default(), U256::default(), true);
   465→
   466→        TransactionSigned::new_unhashed(request, signature)
   467→    }
   468→
   469→    #[test]
   470→    fn cancun_block_incorrect_blob_gas_used() {
   471→        let chain_spec = ChainSpecBuilder::mainnet().cancun_activated().build();
   472→
   473→        // create a tx with 10 blobs
   474→        let transaction = mock_blob_tx(1, 10);
   475→
   476→        let header = Header {
   477→            base_fee_per_gas: Some(1337),
   478→            withdrawals_root: Some(proofs::calculate_withdrawals_root(&[])),
   479→            blob_gas_used: Some(1),
   480→            transactions_root: proofs::calculate_transaction_root(std::slice::from_ref(
   481→                &transaction,
   482→            )),
   483→            ..Default::default()
   484→        };
   485→        let body = BlockBody {
   486→            transactions: vec![transaction],
   487→            ommers: vec![],
   488→            withdrawals: Some(Withdrawals::default()),
   489→        };
   490→
   491→        let block = SealedBlock::seal_slow(alloy_consensus::Block { header, body });
   492→
   493→        // 10 blobs times the blob gas per blob.
   494→        let expected_blob_gas_used = 10 * DATA_GAS_PER_BLOB;
   495→
   496→        // validate blob, it should fail blob gas used validation
   497→        assert_eq!(
   498→            validate_block_pre_execution(&block, &chain_spec),
   499→            Err(ConsensusError::BlobGasUsedDiff(GotExpected {
   500→                got: 1,
   501→                expected: expected_blob_gas_used
   502→            }))
   503→        );
   504→    }
   505→}
